import{c as t,Q as a,j as o,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Claude Fable 5: the exact setup to get maximum quality before the free window closes","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@Mnilax-225770.md","filePath":"research/tweets/2026-06-09-@Mnilax-225770.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-09-@Mnilax-225770.md"};function s(n,e,l,h,d,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="claude-fable-5-the-exact-setup-to-get-maximum-quality-before-the-free-window-closes" tabindex="-1">Claude Fable 5: the exact setup to get maximum quality before the free window closes <a class="header-anchor" href="#claude-fable-5-the-exact-setup-to-get-maximum-quality-before-the-free-window-closes" aria-label="Permalink to &quot;Claude Fable 5: the exact setup to get maximum quality before the free window closes&quot;">​</a></h1><p><strong>作者</strong>：Mnimiy (@Mnilax)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/mnilax/status/2064447011953225770" target="_blank" rel="noreferrer">https://x.com/mnilax/status/2064447011953225770</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 100 · 🔁 7 · 🔖 183 · 👁 13,180</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 完整操作指南：silent fallback 機制（~5% prompts 轉 Opus 4.8）、effort 五段調節、persistent memory 3× 倍增、13 天免費窗口；benchmarks SWE-Bench Pro 80.3% / Terminal-Bench 88.0%。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Fable 5 vs Mythos 5</strong>：同一底層模型，差別只在 safeguards；<code>claude-fable-5</code> 為公開 API model ID；price $10 input / $50 output per M tokens</li><li><strong>Silent Fallback 系統（最重要操作洞察）</strong>：cyber / bio-chem / distillation 三類 prompt → 自動路由到 Opus 4.8，有通知。&gt;95% sessions 不觸發。含義：安全/生科工作直接 call Opus，不要讓 Fable 浪費輪次在 fallback</li><li><strong>三大升級</strong>：Vision（截圖直接 rebuild web app）/ Memory（file-based memory 3× 提升 vs Opus 4.8）/ Token efficiency（medium effort 已勝 Opus max）</li><li><strong>Exact Setup</strong>：Claude Code <code>/model</code> 選 Fable 5 → <code>d</code> 設為 default；<code>/effort xhigh</code>（migrations/long tasks）/ <code>medium</code>（everyday）；max 多為 diminishing returns；persistent memory files = 長任務 force multiplier</li><li><strong>30 天 retention</strong>：每個 Fable request 保留 30 天分析 jailbreak/distillation，不訓練新模型；不 jailbreak = 安全</li></ol><h3 id="關鍵數據" tabindex="-1">關鍵數據 <a class="header-anchor" href="#關鍵數據" aria-label="Permalink to &quot;關鍵數據&quot;">​</a></h3><ul><li>SWE-Bench Pro：80.3%（vs Opus 4.8：69.2%，GPT 5.5：58.6%，Gemini 3.1 Pro：54.2%）</li><li>Terminal-Bench 2.1：88.0%；GDPval-AA knowledge work：1932 vs Opus 4.8&#39;s 1890</li><li>Fallback rate：&gt;95% 不觸發；offensive-task: 5.4%（Fable）vs 56.6%（Opus 4.8）vs 83.2%（Opus 4.6）</li><li>Memory test：Fable file-based memory 3× better than Opus 4.8 in Slay the Spire experiment</li><li>Stripe：50M-line Ruby codebase migration in 1 day（vs team 2+ months）</li><li>免費窗口：Pro/Max/Team 至 2026-06-22；6/23 起按 API 計費</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>文章是 launch day 個人測試，非 Anthropic 官方；fallback 統計引用 Anthropic 公告來源</li><li>Effort level guidance（xhigh &gt; medium &gt; max diminishing）與 cc-workspace CLAUDE.md 定義一致——高度可信</li><li>30 天 retention 屬 Anthropic policy，用戶須自行確認是否與客戶數據合規</li><li>免費窗口 13 天有時效性；核心 setup 規則（effort/memory/fallback）在收費後仍適用</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>9/10</td><td><code>/effort xhigh</code> + persistent memory + fallback routing 全可立即套用 cc-workspace</td></tr><tr><td>B. 創新性</td><td>7/10</td><td>Silent fallback 機制、effort &gt; model 優先、memory 3× 倍增是非顯見洞察</td></tr><tr><td>C. 證據品質</td><td>7/10</td><td>多個具體 benchmark 數據 + Stripe 案例 + Slay the Spire 實測；launch-day 個人測試有限制</td></tr><tr><td>D. 技術深度</td><td>7/10</td><td>API model ID / max_tokens / effort level 五段 / session-only vs settings 有可執行細節</td></tr><tr><td>E. 泛化性</td><td>5/10</td><td>高度 Fable 5 專屬；effort as lever 原則 + fallback 概念可泛化</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.30/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>CLAUDE.md</code> / <code>core.md</code>：effort 使用規範（xhigh 長任務、medium 日常、max 謹慎）；fallback-aware routing（cyber/bio/distill → 直接用 Opus）；persistent memory = 長任務 force multiplier<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>On roughly 1 in 20 prompts, the most capable Claude model ever shipped won&#39;t be the one answering you. Most people will flip the dropdown to Fable 5 today and never notice the three flagged areas where it quietly hands the prompt to a weaker model, or that the free access closes in 13 days. I spent launch day putting it on four real projects and mapping every fallback trigger and config knob, so you don&#39;t burn the window guessing. Below: the exact setup to pull maximum Fable 5 quality before the meter turns on, where it silently routes you to Opus 4.8, and the bugs it surfaced that nothing caught for months.</p><h1 id="what-actually-shipped" tabindex="-1">What actually shipped <a class="header-anchor" href="#what-actually-shipped" aria-label="Permalink to &quot;What actually shipped&quot;">​</a></h1><p>Two models, one brain. Fable 5 is the new flagship, available to everyone. Mythos 5 is the same underlying model with the cybersecurity safeguards lifted, restricted to Project Glasswing partners and a coming trusted-access program. The only thing separating the two is the safeguards. The name is the tell: fable comes from the Latin fabula, &quot;that which is told,&quot; a sibling in meaning to the Greek mythos. It is the strongest model Anthropic has ever put in front of the public. On SWE-Bench Pro it scores 80.3% against Opus 4.8&#39;s 69.2%, GPT 5.5&#39;s 58.6%, and Gemini 3.1 Pro&#39;s 54.2%. On Terminal-Bench 2.1, 88.0%. On GDPval-AA knowledge work, 1932 to Opus 4.8&#39;s 1890. The pattern that matters more than any single number: the longer and more complex the task, the bigger the lead. This is not a model that wins on one-liners. It wins on the jobs you&#39;ve been afraid to hand off. Price is $10 per million input tokens, $50 per million output. Less than half of what Mythos Preview cost. The advantage compounds on big work. In early testing, Stripe ran a codebase-wide migration on a 50-million-line Ruby codebase in a single day, work that would have taken a team over two months by hand.</p><h1 id="the-silent-fallback-5-of-the-time-you-re-not-talking-to-fable" tabindex="-1">The silent fallback: ~5% of the time you&#39;re not talking to Fable <a class="header-anchor" href="#the-silent-fallback-5-of-the-time-you-re-not-talking-to-fable" aria-label="Permalink to &quot;The silent fallback: ~5% of the time you&#39;re not talking to Fable&quot;">​</a></h1><p>This is the part nobody is going to read in the announcement, and it changes how you route work. Fable ships with a set of classifiers: separate systems that watch each prompt. When a request looks like it touches cybersecurity, biology and chemistry, or distillation, the response is handled by Claude Opus 4.8 instead of Fable, and you get told it happened. More than 95% of sessions never hit a fallback. For those sessions, Fable 5 is effectively identical to Mythos 5. The premium model is the default experience. But if your work lives in one of those three buckets, you are often getting Opus 4.8, not the flagship you selected. Three things to internalize:</p><ul><li>Security work falls back, by design. The cyber classifier is built to stop Fable from making progress on offensive tasks. Under automated red-teaming, Fable&#39;s offensive-task success rate sits at 5.4%, down from Opus 4.8&#39;s 56.6% and Opus 4.6&#39;s 83.2%. That&#39;s not Fable being worse at security. That&#39;s the safeguard doing exactly its job. If you do pentest, exploit, or red-team work, expect the fallback and don&#39;t waste turns fighting it.</li><li>Bio and chem are netted broadly right now. Anthropic tuned these conservatively to ship safely and fast, which means even benign chemistry or biology questions can trigger a fallback. They&#39;ve said they&#39;ll narrow it. Until then, treat any life-sciences prompt as likely-Opus.</li><li>Distillation-shaped prompts fall back too. Anything that reads like an attempt to extract the model&#39;s capabilities to train a competitor gets routed to Opus 4.8.</li></ul><p>The tell is simple: you get a notice when it happens. If you see that notice on a topic you didn&#39;t expect, that&#39;s a false positive, and Anthropic openly admits the net is wide for now. Rephrase, or accept Opus 4.8 for that turn. Don&#39;t read this as a weaker model hidden behind a switch. Read it as routing information: send flagged work knowing Opus answers it, and send everything else to Fable while it&#39;s free.</p><h1 id="what-they-actually-upgraded" tabindex="-1">What they actually upgraded <a class="header-anchor" href="#what-they-actually-upgraded" aria-label="Permalink to &quot;What they actually upgraded&quot;">​</a></h1><p>The bars are loud. Three quieter upgrades matter more for daily work.</p><ul><li>Vision is the real headline. Fable can rebuild a web app&#39;s source code from screenshots alone. The demo that proves it: it beat Pokémon FireRed start to finish using a vision-only harness, no maps, no game-state parsing, no navigation aids, just raw screen pixels.</li></ul><p>Earlier Claude models needed a scaffold of helper tools to play at all. If your work is screenshot to code, scientific figure to numbers, or UI to spec, this is the jump that pays for the model.</p><ul><li>Memory compounds now. Fable stays coherent across millions of tokens and improves its output from its own notes. Given file-based memory in a long game of Slay the Spire, it improved 3x more than Opus 4.8 did with the same memory, and reached the final act three times as often.</li></ul><p>Persistent memory files were a minor optimization before. With Fable they&#39;re a force multiplier. Turn them on for any long-running task.</p><ul><li>It&#39;s token-efficient at lower effort. On Cognition&#39;s FrontierCode benchmark, Fable leads frontier models even at medium effort. You do not have to crank it to maximum to beat Opus. Fable at medium already clears Opus 4.8 at its highest setting, for less money per task.</li></ul><h1 id="the-exact-setup-copy-paste" tabindex="-1">The exact setup (copy-paste) <a class="header-anchor" href="#the-exact-setup-copy-paste" aria-label="Permalink to &quot;The exact setup (copy-paste)&quot;">​</a></h1><ol><li>Set the model. In Claude Code it&#39;s already live on Pro, Max, and Team. Switch in-session with /model, pick Claude Fable 5, and press d in the picker to make it your default. To persist it without touching the picker:</li></ol><p>On the API the model id is <code>claude-fable-5</code>. At xhigh or max give it room to think and run subagents: start max_tokens around 64k and tune down.</p><ol start="2"><li>Pick effort on purpose: it&#39;s a bigger lever than the model. Fable runs five levels: low, medium, high, xhigh, max. Anthropic&#39;s own recommendation is xhigh for real coding and agent runs. The cost curve says you often don&#39;t need to go higher: on FrontierCode&#39;s hardest tasks, Fable at medium already clears Opus 4.8 at its max, for a few dollars a task.</li></ol><p>So the rule: xhigh for the long-horizon jobs you&#39;re spending the free window on (migrations, deep research, root-cause hunts), medium for everyday edits and questions, and treat max as mostly diminishing returns. In Claude Code, run <code>/effort xhigh</code> per session, or set effortLevel once in settings. Note max and ultracode are session-only. Set those with /effort, not in the settings file.</p><ol start="3"><li><p>Turn persistent memory on for long tasks. This is where the 3x lift lives. A long migration or a multi-session refactor with file-based memory is a different model than the same task without it.</p></li><li><p>Know when NOT to reach for Fable. Two cases. First, short, cheap, deterministic prompts where Opus 4.8 or Sonnet returns the same answer for less money. The $10/$50 premium buys nothing there. Second, anything in the cyber, bio/chem, or distillation buckets. You&#39;ll get Opus 4.8 anyway, so call Opus directly and skip the fallback notice.</p></li><li><p>Mind the data retention. Every Fable request is now retained for 30 days and analyzed in the background, specifically to catch jailbreak and distillation attempts and to reduce false positives. It is not used to train new models, and it&#39;s deleted after 30 days. But keep the retention in mind for sensitive client data, and don&#39;t try to jailbreak or extract anything: catching exactly that is what the retention exists for.</p></li></ol><h2 id="worth-it-vs-overkill" tabindex="-1">Worth it vs overkill <a class="header-anchor" href="#worth-it-vs-overkill" aria-label="Permalink to &quot;Worth it vs overkill&quot;">​</a></h2><p>Where the edge is real:</p><ul><li>Long-horizon coding. Codebase-wide migrations, multi-file refactors, anything where the task runs long enough for the lead to compound. This is the model&#39;s home turf.</li><li>Vision. Screenshot to working code, dense scientific figures to extracted numbers, a UI to a spec. State-of-the-art, and a genuine jump over Opus.</li><li>Senior-grade analysis. Finance, research, root-cause. One physics research partner reported Fable reached in 36 hours roughly where GPT-5.5 landed after four days, using a third of the reasoning tokens. Hebbia rated it the strongest finance model they&#39;ve tested.</li></ul><h2 id="where-it-s-overkill" tabindex="-1">Where it&#39;s overkill: <a class="header-anchor" href="#where-it-s-overkill" aria-label="Permalink to &quot;Where it&#39;s overkill:&quot;">​</a></h2><ul><li>Short, cheap, deterministic tasks. If Opus 4.8 or Sonnet gives the identical answer, the premium buys you nothing. Don&#39;t run a flagship to reformat JSON.</li><li>Flagged-topic work. You&#39;re getting Opus 4.8 on those prompts regardless. Use Opus directly.</li></ul><p>One trust note worth stating plainly, because the safety story scares people off: Fable and Mythos 5 are the same model, and on Anthropic&#39;s alignment assessment Mythos 5&#39;s misaligned behavior measured on par with Opus 4.8 and below earlier models. More capability did not come with a measurable alignment regression.</p><h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>You&#39;re not upgrading a chatbot. You&#39;re getting a 13-day free trial of a senior operator with three traits: it gets stronger the longer the task runs, it reads screens like text now, and it steps aside for a junior on three flagged areas.</p><p>So spend the trial on the work that&#39;s been too big or too slow to hand off. Not the quick stuff you&#39;d give any model. The migration, the audit, the refactor, the analysis you keep pushing to next quarter. That&#39;s what closes on June 23.</p><h1 id="what-it-found-in-my-projects" tabindex="-1">What it found in my projects <a class="header-anchor" href="#what-it-found-in-my-projects" aria-label="Permalink to &quot;What it found in my projects&quot;">​</a></h1><p>I didn&#39;t want to review Fable on benchmarks. I wanted to see what it does on code I already know cold. So on launch day I opened four Claude Code sessions, one per active project, and gave each the same instruction. Not &quot;add a feature.&quot; Just: look at this codebase the way a senior who&#39;s never seen it would.</p><p>It surfaced bugs that months of prior Opus work on the same code had walked straight past. On my wallet parser, 9 of them. On a closed project I can&#39;t get into yet, 4 more. What stood out wasn&#39;t the count. It was the category: not more of what Opus already finds, but the bugs that need the whole file held in working memory at once to even notice, the ones hiding in the seams between functions. That&#39;s the long-context and vision upgrade showing up in real work, not on a leaderboard.</p><h2 id="the-catch-it-s-a-13-day-free-window-not-a-gift" tabindex="-1">The catch: it&#39;s a 13-day free window, not a gift <a class="header-anchor" href="#the-catch-it-s-a-13-day-free-window-not-a-gift" aria-label="Permalink to &quot;The catch: it&#39;s a 13-day free window, not a gift&quot;">​</a></h2><p>One thing decides your next two weeks. Read the rollout terms, not the headline. From today through June 22, Fable 5 is included on Pro, Max, Team, and seat-based Enterprise at no extra cost. On June 23, it gets pulled from those plans. After that, using it costs usage credits at the API rate: $10 in, $50 out. Anthropic says they aim to fold it back into subscriptions &quot;when capacity allows.&quot; That&#39;s an intention, not a date. So you have 13 days of a frontier model for the price of a plan you already pay for. The operator move is obvious: front-load your highest-value, highest-effort work onto Fable now. The migration you keep postponing, the refactor across 40 files, the audit that&#39;s too big for a normal session. Not &quot;summarize this email.&quot;</p><h2 id="closing" tabindex="-1">Closing <a class="header-anchor" href="#closing" aria-label="Permalink to &quot;Closing&quot;">​</a></h2><p>You&#39;ve got 13 days with the strongest model Anthropic has ever shipped to everyone, on a plan you already pay for. Whatever big, slow, scary task you&#39;ve been saving for &quot;when I have time,&quot; this is the window. Put it on Fable tonight.</p><blockquote><p>Bookmark this and set Fable 5 as your model and run your biggest task before June 23.</p></blockquote><p>Repost if it saved you from sleeping through the free window.</p><p>Telegram for the weekly Claude operator notes: <a href="https://t.me/+fzoUEFYE5Q0xZjky" target="_blank" rel="noreferrer">https://t.me/+fzoUEFYE5Q0xZjky</a></p>',56)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
